#!/usr/bin/env python3
"""Synchronize CaiYunAds to Surge, including requested client membership flags.

Keep the original JavaScript byte-for-byte, behind a bounded Surge compatibility
bridge. Include all upstream rules and the optional biz.cyapi.cn MITM hostname
explicitly requested by the user. No real subscription, shared account or token
is supplied. Unknown directives and invalid script downloads fail before writes.
"""
from __future__ import annotations

import argparse
import hashlib
import re
import subprocess
import sys
import tempfile
import urllib.request
from pathlib import Path
from urllib.parse import urlparse

UPSTREAM_URL = "https://raw.githubusercontent.com/ddgksf2013/Rewrite/master/AdBlock/CaiYunAds.conf"
MODULE_PATH = Path("Surge/Module/CaiYunAds.sgmodule")
ASSET_PATH = Path("Surge/JavaScript/CaiYun")
RAW_ROOT = "https://raw.githubusercontent.com/Polly-ai/Wynston/main"
SCRIPT_URL = "https://raw.githubusercontent.com/ddgksf2013/Scripts/refs/heads/master/caiyun_json.js"
ALLOWED_HOSTS = {"wrapper.cyapi.cn", "api.caiyunapp.com", "starplucker.cyapi.cn", "ad.cyapi.cn", "biz.cyapi.cn"}
AD_ENDPOINTS = (
    ("wrapper.cyapi.cn", "activity"),
    ("api.caiyunapp.com", "activity"),
    ("starplucker.cyapi.cn", "operation/homefeatures"),
    ("starplucker.cyapi.cn", "notification/message_center"),
    ("starplucker.cyapi.cn", "config/cypage"),
    ("starplucker.cyapi.cn", "operation/feeds"),
    ("starplucker.cyapi.cn", "operation/banners"),
    ("starplucker.cyapi.cn", "operation/features"),
    ("starplucker.cyapi.cn", "campaigns"),
)
VIP_PATTERNS = {
    r"^https?:\/\/biz\.cyapi\.cn\/api\/v\d\/user_detail",
    r"^https?:\/\/biz\.cyapi\.cn\/v\d\/user",
}
EMPTY_JS = '''// CaiYun adapter: preserve upstream reject-200 response semantics.
// Generated by Polly-ai/Wynston, based on @ddgksf2013's rule.
$done({response:{status:200,headers:{"Content-Type":"text/plain; charset=utf-8",
  "Cache-Control":"no-store"},body:""}});
'''


class SyncError(ValueError):
    pass


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def fetch(url: str) -> str:
    if urlparse(url).scheme != "https":
        raise SyncError("Unverified or non-HTTPS source")
    error = None
    for _ in range(3):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent":"Wynston-CaiYun-Sync/1.0", "Cache-Control":"no-cache"})
            with urllib.request.urlopen(req, timeout=45) as response:
                if response.status != 200:
                    raise SyncError(f"HTTP {response.status}")
                data = response.read(2_000_001)
                if len(data) > 2_000_000:
                    raise SyncError("Unexpected source exceeds 2 MB")
                text = data.decode("utf-8-sig")
                if not text.strip() or text.lstrip().lower().startswith(("<html", "<!doctype html")):
                    raise SyncError("Empty or HTML source")
                return text
        except Exception as exc:
            error = exc
    raise SyncError(f"Download failed: {url}: {error}")


def metadata(text: str, key: str) -> str:
    match = re.search(r"^\s*//\s*@" + re.escape(key) + r"\s+(.+?)\s*$", text, re.M)
    return match.group(1) if match else "未标注"


def classify(pattern: str) -> str:
    """Recognize exact upstream endpoints without trusting freeform regex."""
    normalized = pattern.replace(r"\/", "/")
    for host, path in AD_ENDPOINTS:
        expected = "^https?://" + host.replace(".", r"\.") + r"/v\d/" + path
        if normalized == expected:
            return "response"
    if normalized == r"^https?://ad\.cyapi\.cn/v\d":
        return "empty"
    raise SyncError("New URL endpoint requires explicit compatibility review")


def parse(text: str):
    hosts, rules, vip_rules = [], [], []
    patterns = set()
    comment = ""
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        if line.startswith(("//", "#", ";")):
            if line.startswith("# >"):
                comment = line
            continue
        match = re.fullmatch(r"hostname\s*=\s*(.+)", line)
        if match:
            for host in match.group(1).split(","):
                host = host.strip()
                if host not in ALLOWED_HOSTS:
                    raise SyncError(f"Line {number}: new MITM hostname requires review")
                if host not in hosts:
                    hosts.append(host)
            continue
        match = re.fullmatch(r"(\^\S+)\s+url\s+(\S+)(?:\s+(https://\S+))?", line)
        if not match:
            raise SyncError(f"Line {number}: unknown upstream directive")
        pattern, action, source = match.groups()
        if pattern in patterns:
            raise SyncError("Duplicate URL pattern")
        patterns.add(pattern)
        try:
            re.compile(pattern)
        except re.error as exc:
            raise SyncError("Invalid upstream URL regex") from exc
        if pattern in VIP_PATTERNS:
            if action != "script-response-body" or source != SCRIPT_URL:
                raise SyncError("Changed membership directive requires review")
            vip_rules.append(pattern)
            rules.append((pattern, "vip", comment))
            comment = ""
            continue
        mode = classify(pattern)
        if ((mode == "response" and (action != "script-response-body" or source != SCRIPT_URL)) or
                (mode == "empty" and (action != "reject-200" or source is not None))):
            raise SyncError("Unexpected ad action or JavaScript source")
        rules.append((pattern, mode, comment))
        comment = ""
    if not hosts or not rules or not any(mode == "response" for _,mode,_ in rules):
        raise SyncError("Missing ad rules or MITM hostnames")
    if vip_rules and "biz.cyapi.cn" not in hosts:
        hosts.append("biz.cyapi.cn")
    return hosts, rules, vip_rules


def build_bridge(source: str) -> str:
    """Embed upstream intact; canonicalize matching URLs and fail open on errors."""
    prefix = r'''// Surge compatibility bridge; original @ddgksf2013 script follows intact.
// Generated by Polly-ai/Wynston. No credentials or actual subscriptions supplied.
(function (request, response, finish) {
  let first, calls = 0;
  function capture(result) { if (calls === 0) first = result; calls++; }
  try {
    if (!request || !response || typeof request.url !== "string" ||
        typeof response.body !== "string") { finish({}); return; }
    if (typeof response.status === "number" && (response.status < 200 || response.status >= 300)) {
      finish({}); return;
    }
    // Preserve invalid/empty/error responses, rather than replacing them with fake JSON.
    JSON.parse(response.body);
    const parts = request.url.match(/^https?:\/\/([^/?#]+)(\/[^?#]*)(?:\?([^#]*))?/);
    if (!parts) { finish({}); return; }
    const host = parts[1].toLowerCase(), path = parts[2], query = parts[3] || "";
    let match, canonical = "";
    if ((host === "wrapper.cyapi.cn" || host === "api.caiyunapp.com") &&
        (match = path.match(/^\/v(\d)\/activity/))) {
      canonical = "/v" + match[1] + "/activity";
      if (/(?:^|&)type_id=A03(?:&|$)/.test(query)) canonical += "?type_id=A03";
    } else if (host === "starplucker.cyapi.cn" &&
        (match = path.match(/^\/v(\d)\/(operation\/(?:homefeatures|feeds|banners|features)|notification\/message_center|config\/cypage|campaigns)/))) {
      canonical = "/v" + match[1] + "/" + match[2];
    } else if (host === "biz.cyapi.cn" &&
        (match = path.match(/^\/api\/v(\d)\/user_detail/))) {
      canonical = "/api/v" + match[1] + "/user_detail";
    } else if (host === "biz.cyapi.cn" && (match = path.match(/^\/v(\d)\/user/))) {
      canonical = "/v" + match[1] + "/user";
    }
    if (!canonical) { finish({}); return; }
    // Only the local script view changes. Never send or log account URLs/tokens.
    const localRequest = Object.assign({}, request, {url:"https://" + host + canonical});
    (function ($request, $response, $done) {
'''
    suffix = '''
    })(localRequest, response, capture);
  } catch (_) { finish({}); return; }
  const valid = calls > 0 && first && typeof first === "object" && !Array.isArray(first) &&
    (!Object.prototype.hasOwnProperty.call(first, "body") || typeof first.body === "string");
  // Upstream's unknown-path branch can call $done twice: honour the first result.
  finish(valid ? first : {});
})($request, $response, $done);
'''
    return prefix + "// BEGIN upstream caiyun_json.js SHA256 " + sha(source) + "\n" + source + suffix


def render(text: str, source: str) -> str:
    hosts, rules, vip_rules = parse(text)
    out = [
        "#!name = 彩云天气 增强",
        "#!desc = 去除推广与广告，保留上游 VIP/SVIP 客户端标记伪装；会员部分需登录且旧版≤7.20.2，不代表真实订阅。",
        "#!category = Polly-ai",
        f"# 上游来源：{UPSTREAM_URL}",
        f"# 上游版本：{metadata(text, 'Version')}；原作者更新：{metadata(text, 'UpdateTime')}",
        f"# 配置 SHA256：{sha(text)}",
        f"# 上游 caiyun_json.js SHA256：{sha(source)}",
        "# 转换与维护：Polly-ai/Wynston。上游 JS 原样镜像，Surge 桥接处理异常与重复完成。",
        "# 已按用户要求保留两条会员标记规则，并显式追加 biz.cyapi.cn 的 MITM。",
        "# 仅本机修改响应标记；不提供共享账号、真实订阅或服务器端付费权限。",
        "# 需启用 MITM 并信任证书；不要与其他匹配这些接口的响应脚本重复启用。",
        "# 每日同步配置和 JS；无变化不提交，下载或验证失败不发布。",
        "# max-size=1048576：响应超过 1 MiB 时 Surge 跳过脚本并透传。",
        "# [Map Local] 原生返回 HTTP 200 空体；需启用重写（iOS 5.9.1+ / Mac 5.5.1+）。",
        "", "[Script]",
    ]
    for pattern, mode, comment in rules:
        if mode == "empty":
            continue
        if comment:
            out.append(comment.replace("@ddgksf2013", "").rstrip())
        identifier = "caiyun_" + sha(pattern)[:12]
        out.append(f"{identifier} = type=http-response, pattern={pattern}, requires-body=true, "
                   f"max-size=1048576, script-path={RAW_ROOT}/{ASSET_PATH.as_posix()}/caiyun-surge.js, "
                   "script-update-interval=86400, timeout=10")
    mappings = [(pattern, comment) for pattern, mode, comment in rules if mode == "empty"]
    if mappings:
        out.extend(["", "[Map Local]"])
        for pattern, comment in mappings:
            if comment:
                out.append(comment.replace("@ddgksf2013", "").rstrip())
            out.append(f'{pattern} data-type=text data="" status-code=200 '
                       'header="Content-Type:text/plain; charset=utf-8|Cache-Control:no-store"')
    out.extend(["", "[MITM]", "hostname = %APPEND% " + ", ".join(hosts), ""])
    return "\n".join(out)


def validate_scripts(sources: dict[str, str]):
    with tempfile.TemporaryDirectory(prefix="caiyun-sync-") as directory:
        for name, source in sources.items():
            if not source.strip() or "$done" not in source:
                raise SyncError(f"Empty or invalid JavaScript: {name}")
            path = Path(directory) / name
            path.write_bytes(source.encode("utf-8"))
            result = subprocess.run(["node", "--check", str(path)],
                                    capture_output=True, text=True, timeout=15)
            if result.returncode:
                raise SyncError(f"JavaScript syntax error: {name}: {result.stderr[:1000]}")
        harness = r'''
const fs = require('node:fs'), vm = require('node:vm'), assert = require('node:assert/strict');
const dir = process.argv[1];
const parse = x => JSON.parse(x.body);
let total = 0;
function run(name, url, body, status = 200) {
  const calls = [];
  const sandbox = {$request:{url,headers:{}}, $response:{body,status,headers:{}},
    $done:value=>calls.push(value), console:{log(){},warn(){},error(){}}};
  vm.runInNewContext(fs.readFileSync(dir+'/'+name,'utf8'), sandbox,
    {timeout:1500,contextCodeGeneration:{strings:false,wasm:false}});
  assert.equal(calls.length,1,name+': must finish once');
  const result = calls[0];
  assert(result && typeof result === 'object' && !Array.isArray(result));
  assert(!Object.hasOwn(result,'body') || typeof result.body === 'string');
  total++;
  return JSON.parse(JSON.stringify(result));
}
if (fs.existsSync(dir+'/caiyun-reply.js')) {
  const reply=run('caiyun-reply.js','https://ad.cyapi.cn/v1',undefined).response;
  assert.equal(reply.status,200); assert.equal(reply.body,'');
}
if (fs.existsSync(dir+'/caiyun-surge.js')) {
  const name='caiyun-surge.js';
  const cases=[
    ['https://wrapper.cyapi.cn/v1/activity',{},r=>assert.deepEqual(r,{status:'ok',activities:[{items:[{}]}]})],
    ['https://api.caiyunapp.com/v1/activity?type_id=A03',{},r=>assert.deepEqual(r,{status:'ok',activities:[{type:'tabbar',name:'aichat',feature:false}]})],
    ['https://starplucker.cyapi.cn/v1/operation/homefeatures',{},r=>assert.deepEqual(r,{data:[]})],
    ['https://starplucker.cyapi.cn/v1/notification/message_center',{},r=>assert.deepEqual(r,{messages:[]})],
    ['https://starplucker.cyapi.cn/v1/config/cypage',{},r=>assert.deepEqual(r,{popups:[],actions:[]})],
    ['https://starplucker.cyapi.cn/v1/operation/feeds',{data:[{id:1,category_times_text:'123人查看'},{id:2,category_times_text:'推广'}],keep:1},r=>{assert.deepEqual(r.data,[{id:1,category_times_text:'123人查看'}]);assert.equal(r.keep,1);}],
    ['https://starplucker.cyapi.cn/v1/operation/banners',{},r=>{assert.equal(r.data.length,1);assert.equal(r.data[0].banner_type,'article');}],
    ['https://starplucker.cyapi.cn/v1/operation/features',{data:[{url:'cy://weather'},{url:'https://ad.invalid/'}],keep:1},r=>{assert.deepEqual(r.data,[{url:'cy://weather'}]);assert.equal(r.keep,1);}],
    ['https://starplucker.cyapi.cn/v1/campaigns',{},r=>{assert.equal(r.campaigns.length,1);assert.equal(r.campaigns[0].name,'driveweather');}],
    ['https://biz.cyapi.cn/v2/user',{result:{is_vip:0,svip_expired_at:1,wt:{vip:{expired_at:1}},svip_take_effect:0,vip_type:'n'},keep:1},r=>{assert.equal(r.result.is_vip,1);assert.equal(r.result.svip_take_effect,1);assert.equal(r.result.vip_type,'s');assert(r.result.wt.vip.expired_at>1800000000);assert.equal(r.keep,1);}],
    ['https://biz.cyapi.cn/api/v1/user_detail',{vip_info:{vip:{expires_time:'1'},svip:{expires_time:'1'}},keep:1},r=>{assert.equal(r.vip_info.vip.is_auto_renewal,true);assert.equal(r.vip_info.svip.is_auto_renewal,true);assert(Number(r.vip_info.vip.expires_time)>1800000000);assert.equal(r.keep,1);}]
  ];
  for (const [url,input,check] of cases) check(parse(run(name,url,JSON.stringify(input))));
  const url='https://starplucker.cyapi.cn/v1/operation/feeds';
  for (const body of ['',undefined,'<html>error</html>','not JSON','null','{"data":[null]}','{}'])
    assert.deepEqual(run(name,url,body),{});
  assert.deepEqual(run(name,'https://biz.cyapi.cn/v2/user','{}'),{});
  assert.deepEqual(run(name,'https://biz.cyapi.cn/api/v1/user_detail','{}'),{});
  assert.deepEqual(run(name,'https://unrelated.example/v2/user','{}'),{});
  assert.deepEqual(run(name,'https://wrapper.cyapi.cn/v1/unknown','{}'),{});
  // v1/user has no matching branch upstream; duplicate $done must become one pass-through.
  assert.deepEqual(run(name,'https://biz.cyapi.cn/v1/user','{}'),{});
  assert.deepEqual(run(name,'https://biz.cyapi.cn/v2/user','{}',401),{});
  const safe=parse(run(name,'https://wrapper.cyapi.cn/v1/activity?redirect=/v2/user&x=user_detail','{}'));
  assert.equal(safe.status,'ok'); assert(!Object.hasOwn(safe,'result'));
  const tab=parse(run(name,'https://wrapper.cyapi.cn/v1/activity?type_id=A03&x=user_detail','{}'));
  assert.equal(tab.activities[0].feature,false);
  const normal=JSON.stringify({result:{is_vip:0,svip_expired_at:1,wt:{vip:{expired_at:1}}}});
  if (fs.existsSync(dir+'/caiyun_json.js')) {
    const url='https://biz.cyapi.cn/v2/user';
    assert.deepEqual(run('caiyun_json.js',url,normal),run(name,url,normal));
  }
}
console.log('CaiYun runtime checks passed: '+total);
'''
        result = subprocess.run(["node", "-e", harness, directory],
                                capture_output=True, text=True, timeout=45)
        if result.returncode:
            raise SyncError("CaiYun runtime validation failed: " + result.stderr[:1800])
        print(result.stdout.strip())


def prepare(text: str, source: str) -> dict[Path, str]:
    parse(text)
    sources = {"caiyun_json.js": source, "caiyun-surge.js": build_bridge(source),
               "caiyun-reply.js": EMPTY_JS}
    validate_scripts(sources)
    module = render(text, source)
    return {**{ASSET_PATH / name: data for name,data in sources.items()}, MODULE_PATH: module}


def write_changed(path: Path, text: str) -> bool:
    raw = text.encode("utf-8")
    if path.exists() and path.read_bytes() == raw:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".sync-tmp")
    temp.write_bytes(raw)
    temp.replace(path)
    return True


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--from-file", type=Path)
    parser.add_argument("--script-file", type=Path)
    parser.add_argument("--root", type=Path, default=Path("."))
    args = parser.parse_args(argv)
    try:
        text = (args.from_file.read_bytes().decode("utf-8-sig")
                if args.from_file else fetch(UPSTREAM_URL))
        parse(text)
        source = (args.script_file.read_bytes().decode("utf-8-sig")
                  if args.script_file else fetch(SCRIPT_URL))
        files = prepare(text, source)
        changed = [str(path) for path,content in files.items() if write_changed(args.root / path, content)]
        print("sync_caiyun_ads: " + ("updated " + ", ".join(changed) if changed else "no upstream changes"))
        return 0
    except (SyncError, OSError, UnicodeError, subprocess.SubprocessError) as exc:
        print("sync_caiyun_ads: error: " + str(exc), file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
